import json,copy,pathlib,hashlib,re,yaml
base=pathlib.Path('research/quantum-computing-planning'); path=base/'proposed-items.json'; data=json.loads(path.read_text()); items=data['items']; old=copy.deepcopy(items); by={i['id']:i for i in items}; changes={}
pages=json.loads((base/'pages.json').read_text()); pageby={p['label']:p['page'] for p in pages['pages']}
def edit(id,s=None,deps=(),proof=None):
 i=by[id];changes.setdefault(id,[])
 if s is not None and s!=i['statement_or_definition']:i['statement_or_definition']=s;changes[id].append('contract')
 for d in deps:
  if d not in i['deps']:i['deps'].append(d);changes[id].append('supplier '+d)
 if proof is not None:i['proof_obligations']=proof;i['unresolved_obligations']=proof.copy();changes[id].append('proof route')
def add(id,kind,label,s,deps,proof,source='https://cs.uwaterloo.ca/~watrous/TQI/TQI.pdf',locator='Chapters 1–3; finite-dimensional adaptation specified in this contract'):
 assert id not in by
 i={'id':id,'kind':kind,'title':id.split('-qc-')[1].replace('-',' ').capitalize(),'page':pageby[label],'deps':deps,'justified_by':[],'statement_or_definition':s,'proof_obligations':proof,'sources':[{'url':source,'locator':locator}],'existing_supplier_checks':['Proposed local supplier; not an authored or proof-accepted carrier. Exact prerequisites listed; local mathematical route specified.'],'unresolved_obligations':proof.copy()};items.append(i);by[id]=i;changes[id]=['new prerequisite contract']
# Foundations: explicit supplier directions and exact finite domains.
edit('def-qc-tensor-map',deps=['thm-tensor-product-basis-from-bases']);edit('thm-qc-tensor-map-composition-and-adjoint',deps=['lem-qc-tensor-product-basis-and-dimension'])
edit('def-qc-ensemble-and-purification',deps=['def-qc-partial-trace'])
# HJW must not presuppose later POVMs: own earlier finite effect interface.
add('def-qc-finite-positive-effect-family','definition','QC03','On a nonzero finite H, an effect is E≥0 with I−E≥0; a finite complete effect family consists of E_a≥0 with sum E_a=I. This is only algebraic data; no measurement law is used here.',['def-non-negative-and-positive-operator'],['Every member is at most I because its complement is the sum of the others; finite sums preserve positivity.'])
edit('thm-qc-ensemble-purification-correspondence','For a finite pure-state ensemble rho=sum_a p_a |u_a><u_a| (unit u_a), every purification Psi of rho admits a complete effect family E_a on its auxiliary space with Tr_K[(I tensor sqrt(E_a))|Psi><Psi|(I tensor sqrt(E_a))]=p_a|u_a><u_a|. A finite mixed ensemble follows by refining each component spectrally and regrouping. Zero weights give zero effects. No QC04 outcome law is assumed.',deps=['def-qc-finite-positive-effect-family','thm-non-negative-square-root-exists-and-is-unique'],proof=['Use minimal spectral purification sum_j sqrt(lambda_j)e_j tensor f_j. Solve sqrt(rho)v_a=sqrt(p_a)u_a on supp rho by inverse nonzero eigenvalues; sum_a v_av_a† is the support identity.', 'Transpose the v_av_a† matrices in the declared purifying basis to obtain effects; extend by any complete positive splitting of the complementary environment. Compute partial trace directly; transfer to arbitrary padded purification by the earlier support isometry/unitary route. Refine and regroup mixed components.'])
edit('def-qc-povm-and-outcome-law',deps=['def-qc-finite-positive-effect-family'])
edit('thm-qc-hermitian-trace-norm-positive-negative-parts',deps=['thm-qc-trace-norm-spectral-formula'])
edit('thm-qc-trace-norm-rank-one-formula',deps=['def-qc-dirac-notation-conversion'])
edit('thm-qc-partial-trace-positive-and-trace-preserving',deps=['thm-qc-partial-trace-characterization-and-basis-independence'])
edit('thm-qc-channels-compose-and-tensor',deps=['thm-qc-kraus-choi-equivalence','thm-qc-trace-preserving-kraus-normalization','thm-qc-tensor-map-composition-and-adjoint'])
edit('thm-qc-diamond-norm-ancilla-dimension-bound',proof=['Do not reduce arbitrary operators to density matrices. SVD reduces induced trace-norm maximization to rank-one |u><v| with unit u,v on H tensor E.', 'Schmidt-compress u and v separately to ancillary spaces of dimension dim H, using possibly different isometries. Left/right isometric embedding preserves the singular values of the output, so both can be represented on one dim H coordinate space without requiring their original supports to coincide. Compactness of the pair of finite unit spheres yields attainment.'])
edit('thm-qc-channel-diamond-norm-one',deps=['thm-qc-kraus-choi-equivalence','thm-qc-trace-preserving-kraus-normalization','thm-qc-trace-norm-duality-and-norm-properties'],proof=['For the adjoint of each amplified channel, Kraus completeness implies a unital CP map. Prove it sends contractions to contractions by applying it entrywise to the positive 2x2 operator block [[I,B],[B†,I]] for ||B||≤1 (positivity follows by completing the square).', 'Apply trace-norm duality to get contraction on arbitrary X, rather than only Hermitian X. Density input gives norm at least one.'])
edit('thm-qc-fidelity-purification-characterization',deps=['thm-polar-decomposition','thm-qc-trace-norm-duality-and-norm-properties'])
add('lem-qc-fidelity-classical-measurement-minimum','lemma','QC06','For finite density rho,sigma, root fidelity equals min_E sum_a sqrt(tr(rho E_a)tr(sigma E_a)) over complete finite effect families; a projective family attains the minimum.',['def-qc-fidelity','def-qc-povm-and-outcome-law','thm-qc-fidelity-purification-characterization','thm-non-negative-square-root-exists-and-is-unique'],['Purification Cauchy–Schwarz on each effect branch gives F≤classical overlap. For faithful rho diagonalize M=rho^(-1/2)(rho^(1/2)sigma rho^(1/2))^(1/2)rho^(-1/2); M rho M=sigma, so its spectral PVM attains sum sqrt(p_a q_a)=tr(Mrho)=F.', 'For singular rho use rho_epsilon=(1-epsilon)rho+epsilon I/d (and sigma likewise), compactness of ordered d-projector families, a convergent subsequence, and continuity of finite PSD square root/SVD. Prove this finite continuity from convergent spectral decompositions, not an unproved external identity.'],locator='Chapter 3 fidelity: measurement characterization and Fuchs–van de Graaf inequalities')
add('lem-qc-pure-state-trace-distance','lemma','QC06','For unit u,v, D(|u><u|,|v><v|)=sqrt(1−|<u|v>_D|²).',['def-qc-trace-distance','def-qc-dirac-notation-conversion','thm-qc-hermitian-trace-norm-positive-negative-parts'],['Restrict the difference to span(u,v); after phase alignment write v=cu+sqrt(1−c²)w. Its trace-zero 2x2 matrix has eigenvalues ±sqrt(1−c²); handle c=1 directly.'])
edit('thm-qc-fuchs-van-de-graaf',deps=['lem-qc-fidelity-classical-measurement-minimum','lem-qc-pure-state-trace-distance','thm-qc-fidelity-purification-characterization','thm-qc-trace-distance-channel-contractivity'],proof=['For the attaining effect family, 1−sum sqrt(pq)≤(1/2)sum|p−q|≤D by the scalar inequality sqrt(pq)≥min(p,q).', 'Choose maximizing purifications, apply pure-state distance formula, and contract under partial trace to get the upper bound.'])
edit('thm-qc-exact-mixed-state-cloning-fidelity-criterion',deps=['thm-qc-fidelity-range-equality-and-products'])
add('thm-qc-fidelity-range-equality-and-products','theorem','QC06','Root fidelity obeys 0≤F≤1, F=1 iff rho=sigma, F=0 iff supports are orthogonal, and F(rho tensor tau,sigma tensor omega)=F(rho,sigma)F(tau,omega).',['def-qc-fidelity','thm-qc-fidelity-purification-characterization','thm-singular-value-decomposition'],['Purification Cauchy–Schwarz gives upper bound and equality forces equal reduced states; identical states choose the same purification. Trace norm zero means sqrt(rho)sqrt(sigma)=0, equivalent to orthogonal supports. Tensor SVD multiplies singular values and hence trace norms.'])
# Pauli/block semantics.
edit('def-qc-qubit-and-bloch-representation','A qubit is the register C² with ordered computational basis |0>,|1>. A qubit density operator is as defined on QC03; its Bloch representation is introduced by the subsequent coordinate definition and proved in the subsequent existence theorem.')
edit('def-qc-one-qubit-gate-alphabet-and-rotations',s=by['def-qc-one-qubit-gate-alphabet-and-rotations']['statement_or_definition']+' Here theta is real, n is a real unit 3-vector, and exp is the convergent finite-matrix power series; axes of other norm are not called rotations by angle theta.')
edit('thm-qc-bloch-purity-sphere',deps=['thm-qc-rank-one-density-operator','thm-qc-bloch-positivity-ball'],proof=['For a density, eigenvalues are nonnegative and sum one, so tr(rho²)=1 iff precisely one eigenvalue is one; use rank-one density/ray theorem. Pauli trace multiplication gives the displayed formula.'])
edit('def-qc-circuit-denotational-semantics',deps=['lem-qc-local-gate-wire-embedding','lem-qc-disjoint-layer-order-independence'])
edit('lem-qc-coherent-record-isometry',deps=['def-qc-kraus-representation','thm-qc-trace-preserving-kraus-normalization'])
# Reversible compiler and actual finite primitive definitions.
add('def-qc-toffoli-and-fredkin','definition','QC10','On three ordered bits define Toffoli T|a,b,t>=|a,b,t xor ab> and Fredkin F|c,a,b>=|c,a,b> for c=0, |c,b,a> for c=1. Negative-control variants use X conjugation. These are fixed arity-three circuit labels, not black-box arbitrary multicontrol capabilities.',['def-qc-ordered-bitstring-encoding','def-qc-cnot-and-control-target-order'],['Each basis action is a bijection and involution. Fredkin equals chronological CNOT(a,b), Toffoli(c,b,a), CNOT(a,b); test c=0 and c=1, and extend by linearity.'],source='https://www.theory.caltech.edu/~preskill/ph219/chap5_15.pdf',locator='Chapter 5 reversible computation; Boolean reversible gates')
edit('alg-qc-reversible-embedding','Input an explicit topologically ordered bounded-fan-in Boolean DAG over NOT, AND, OR with n inputs, m output ports and constants. Allocate zero work for each gate value and distinct clean scratch for repeated input ports. Evaluate nodes in order: constants use I/X; NOT uses X(t) then CNOT(a,t); AND uses Toffoli(a,b,t); OR uses CNOT(a,t),CNOT(b,t),Toffoli(a,b,t). Copy repeated source ports into distinct scratch by CNOT, use them, and uncopy. CNOT each designated output value into the corresponding arbitrary target y bit. Reverse every compute instruction to restore work. Output the explicit finite gate list implementing |x,y,0_work> to |x,y xor f(x),0_work>. Domain requires a finite DAG; invalid wire references/cycles/unknown labels return INVALID rather than a gate list.',deps=['def-qc-toffoli-and-fredkin','def-boolean-circuit-size-depth-fanin-and-basis','def-qc-clean-and-dirty-ancillas'],proof=['The algorithm gives finite topological loops and inverse-list output; mathematical correctness, clean-work restoration and costs belong to the following results.'])
edit('lem-qc-toffoli-clean-target-and-uncomputation',deps=['def-qc-toffoli-and-fredkin'])
edit('thm-qc-reversible-embedding-cost',deps=['lem-qc-fresh-target-not-and-or-gadgets'],proof=['For each fresh target the exact truth tables give NOT=1 xor a, AND=ab, OR=a xor b xor ab. Distinct port scratch avoids illegally repeated Toffoli wires when a gate uses the same source twice.', 'Induct over the topological list on computational basis inputs. Copy the m outputs before reversing compute, leaving inputs intact; apply linearity to arbitrary superpositions and references. Count every compute/inverse/port copy occurrence to obtain O(S+E+m) gates/work and serial depth.'])
edit('thm-qc-phase-kickback-from-xor-oracle',s='For a Boolean-output f:{0,1}^n→{0,1}, target |−> gives O_f(|x>|−>)=(−1)^{f(x)}|x>|−>; extend by linearity. For m-bit output and character target |chi_s>=2^(−m/2)sum_y(−1)^(s·y)|y>, the phase is (−1)^(s·f(x)).',deps=['def-qc-one-qubit-gate-alphabet-and-rotations'])
# exact synthesis, proof suppliers and resource meaning.
edit('thm-qc-multicontrolled-ancilla-resource-tradeoff',s='For m≥1 controls and exact U in U(2), Barenco gives a chosen no-workspace construction with O(m²) one-qubit/CNOT gates and a chosen one-clean-work-bit construction with O(m) such gates, returning that bit to zero. These are upper bounds; the source has only an Omega(m) lower bound for nonscalar U. Its explicit quadratic construction has Theta(m²) size, which is not a quadratic optimality theorem.',proof=['Expand Barenco Lemma 7.5 recursion C_m=C_(m−1)+O(m), with exact square-root V²=U and controlled-V/V† base decomposition, to derive the no-work bound.', 'For the extra-clean-bit version reproduce Lemma 7.11 with Cor.7.4 controlled-NOT ladders and check the extra bit returns zero on each basis input. Align the same m control count before comparing; source Cor.7.6/7.12 do not prove quadratic optimality.'])
edit('thm-qc-clean-ancilla-multicontrolled-tradeoff',s='Reuse the explicit O(m²) no-workspace and O(m) one-clean-bit exact constructions from QC11, with total widths m+1 and m+2 and exact return of the clean bit; these compare construction upper bounds rather than optimal complexities.')
edit('alg-qc-two-level-unitary-elimination',s='Exact-arithmetic input U in U(N), N≥1, with matrix entries supporting addition, multiplication, conjugation, nonnegative square root and exact zero test. Set M=U and record an empty word. For column j=0,...,N−2 and row r=N−1,...,j+1, let a=M_(r−1,j), b=M_(r,j); if b=0 skip. Otherwise h=sqrt(|a|²+|b|²)>0, apply on rows r−1,r the Givens [[conj(a)/h,conj(b)/h],[−b/h,a/h]], update M and record the factor. Return recorded factors in reverse adjoint order followed by diagonal M. This is a finite exact-arithmetic procedure; a Cauchy name alone does not supply its zero test.')
edit('alg-qc-two-level-gate-to-elementary-gates',s='Input ordered distinct n-bit x,y and exact V in U(2), n≥1. Form the Gray path g0=x,...,gd=y by flipping differing positions in increasing order. For j=0,...,d−2 swap g_j,g_(j+1) using X on the changing bit controlled on all other bits matching their common pattern. The resulting permutation P sends x to g_(d−1) and fixes y. Apply V on the final differing bit controlled on their common other bits, reordering its two basis entries if the bit in g_(d−1) is 1. Undo the swaps in reverse order. Expand every multicontrol using the declared QC11 construction with either no work or one clean bit; emit negative controls as X conjugations.',deps=['def-qc-ordered-bitstring-encoding','thm-qc-multicontrolled-ancilla-resource-tradeoff'])
# Bell preparation is chronological H then CNOT, decoding the reverse.
edit('thm-qc-bell-transform-inverse',s='The Bell preparation transform B=CNOT_(first→second)(H tensor I) applies H first and CNOT second. It sends |ab> to (I tensor X^b)(Z^a tensor I)|Phi+>. Its inverse B†=(H tensor I)CNOT applies CNOT then H and decodes those ordered Bell labels.',proof=['Evaluate H|a> tensor |b>, then CNOT: result (|0,b>+(−1)^a|1,b xor 1>)/sqrt2. This lists Phi+,Psi+,Phi−,Psi− in labels 00,01,10,11.', 'Use H†=H and CNOT†=CNOT to reverse chronological order and recover each input exactly.'])
edit('alg-qc-dense-coding',s='Input classical bits a,b and preshared |Phi+> on Alice A and Bob B. Alice applies X_A^b then Z_A^a (operator Z^a X^b), transmits register A, and Bob applies CNOT_(A→B) followed by H_A and measures ordered AB in the computational basis. Output measured (a,b); branch phase (−1)^(ab) does not affect that output law.',deps=['def-qc-pauli-matrices','def-qc-cnot-and-control-target-order'])
edit('alg-qc-teleportation',deps=['def-qc-cnot-and-control-target-order','def-qc-pauli-matrices','def-qc-projective-measurement'])
# Partial output measurement.
edit('def-qc-quantum-acceptance-probability',s='Let psi_x=U_C|x,0^a> and let O be the named measured output-wire tuple. For z in {0,1}^|O|, define p(z|x)=sum_w |<z,w|P_O psi_x>_D|², where w ranges over every unmeasured wire and P_O is the declared permutation putting O first. Define p_C(x)=sum_(z:accept(x,z)=1) p(z|x)=tr[(sum_accept |z><z| tensor I)P_O|psi_x><psi_x|P_O†]. The bra conversion is <z,w|psi>_D=<psi,z,w>_root. Normalization and range belong to the following proved supplier.',deps=['def-qc-povm-and-outcome-law','def-qc-tensor-register-and-permutation'])
add('thm-qc-output-acceptance-law-normalizes','theorem','QC14','The partial-output law in def-qc-quantum-acceptance-probability is a finite probability distribution, p_C(x) lies in [0,1], and it equals the outcome law of the named computational-basis projective measurement on O.',['def-qc-quantum-acceptance-probability','thm-qc-povm-probabilities-normalize','thm-qc-partial-trace-characterization-and-basis-independence'],['The effects |z><z| tensor I are orthogonal positive projections and sum to identity. Coordinate trace contracts the unmeasured w index; unitary preparation has trace one. Apply the finite POVM normalization theorem.'],source='https://arxiv.org/pdf/0804.3401',locator='Section 2 quantum circuit definitions and acceptance')
by['def-qc-quantum-acceptance-probability']['justified_by']=['thm-qc-output-acceptance-law-normalizes']
edit('thm-qc-bounded-error-amplification-correct',deps=['thm-qc-output-acceptance-law-normalizes'])
edit('alg-qc-bounded-error-amplification',s='Input a uniform family generator, computable rational endpoints 0≤b(n)<a(n)≤1 with gap gamma≥1/p(n), and rational 0<delta(n)≤1/2 with polynomially bounded log(1/delta). Obtain a rational upper bound L≥ln(1/delta) by certified rational interval evaluation of the exponential/logarithm, then choose integer r≥2 gamma^(−2)L. Emit r disjoint copies including their clean ancillas; measure their named output registers and evaluate the original acceptance predicate separately, giving integer successes S. Accept iff 2S≥r(a+b), using exact rational arithmetic. Return the gate list, register layout and this deterministic threshold predicate; incorrect input bounds return INVALID.',proof=['Finite copy loop and exact integer/rational threshold define the procedure. Prove independent Bernoulli errors and the resource/uniformity bounds in the separate theorem. Exact ceiling of an irrational logarithm is not presumed computable from equality testing.'])
# Stabilizer/CSS errors and redundant re-use.
edit('def-qc-pauli-measurement-branch-semantics',s=by['def-qc-pauli-measurement-branch-semantics']['statement_or_definition']+' Here M is a Hermitian Pauli (M†=M, M²=I), not an arbitrary phase-aware Pauli.',deps=['thm-qc-hermitian-pauli-phase-criterion'])
edit('def-qc-stabilizer-state',s='A pure stabilizer state is a ray in the joint +1 fixed space of a rank-n stabilizer subgroup; existence and uniqueness are discharged by the subsequent projector-rank theorem.')
by['def-qc-stabilizer-state']['justified_by']=['thm-qc-stabilizer-projector-rank-and-code-dimension'];edit('thm-qc-stabilizer-projector-rank-and-code-dimension',deps=['def-qc-stabilizer-state'])
edit('thm-qc-stabilizer-projector-and-dimension',deps=['thm-qc-stabilizer-projector-rank-and-code-dimension'],proof=['Identify the same subgroup/rank convention as QC16 and directly reuse its proved average-projector/rank theorem; do not duplicate the proof.'])
edit('def-qc-stabilizer-syndrome-and-logical-operators',s='For Pauli errors E and ordered Hermitian generators g_j, syndrome bit j is 0 for Eg_j=g_jE and 1 for Eg_j=−g_jE. Let Z(P_n)={i^k I}. Logical Pauli classes are the quotient N_(P_n)(S)/(Z(P_n)S); a logically nontrivial Pauli lies in N_(P_n)(S) minus Z(P_n)S. Scalar phases and stabilizers act trivially on logical rays.')
edit('def-qc-stabilizer-distance',s='For a stabilizer code encoding k>0 qubits, d is the minimum weight of E in N_(P_n)(S) minus Z(P_n)S. For k=0 define d=+infinity. This is a set difference, not a product N(S)S, and excludes nontrivial scalar phases of stabilizers.')
edit('thm-qc-stabilizer-distance-detection-and-correction',deps=['thm-qc-stabilizer-projector-and-dimension'],proof=['If a Pauli anticommutes with a stabilizer, PEP=0. If it commutes and has weight below d, it belongs to Z(P_n)S and PEP is a scalar P.', 'For error pairs of weight ≤t, their product has weight ≤2t<d; apply the preceding dichotomy to each product and then KL. General local errors follow from expansion in the tensor-Pauli basis.'])
edit('def-qc-css-code-from-nested-binary-codes',s='For C2⊆C1≤F2^n, define coset vectors |x+C2>=|C2|^(−1/2)sum_(c∈C2)|x+c>, for x in C1/C2. No extra C2-perp⊆C1 condition is needed for this nested-code convention. Choose ordered bases of C2 and a complement in C1 to identify logical labels; k=dim C1−dim C2, including k=0.')
edit('ex-qc-css-nested-code-parameters',s='For C2⊆C1≤F2^n, k=dim C1−dim C2; X checks from C2 commute with Z checks from C1-perp since C2⊆C1. The orthogonal coset states give dimension 2^k. No additional C2-perp inclusion is assumed.')
edit('thm-qc-css-syndrome-correction',s='For the nested-code convention C2⊆C1 and X checks C2, Z checks C1-perp, any bounded-weight CSS recovery guaranteed by KL corrects t arbitrary qubit errors when 2t<min(d(C1),d(C2-perp)), with zero-code distances +infinity. Use syndrome decoders for C1 to correct X components and C2-perp to correct Z components; more precise distances are min wt(C1 minus C2) and min wt(C2-perp minus C1-perp).',deps=['def-qc-generator-and-parity-check-matrices','def-qc-hamming-weight-distance-and-linear-code-distance'])
# Subsystem statement must be an embedded equality.
edit('def-qc-correctable-subsystem-and-gauge-factor',s='A subsystem code is an isometry J:H_G tensor H_L→H_P with nonzero finite G,L and projector P=JJ†. Exact correctability of L for N means there is a CPTP recovery into the embedded code whose decoded logical marginal equals Tr_G(input) for every state on G tensor L, including correlations with an arbitrary finite reference. Gauge output may change. Equivalently the corrected decoded channel equals T_G tensor id_L for some channel T_G, after a permitted gauge reset.',deps=['def-qc-quantum-channel','def-qc-partial-trace'])
edit('thm-qc-subsystem-knill-laflamme',s='For a CPTP N with Kraus E_a and fixed isometry J:G tensor L→H_P, the protected subsystem L is exactly correctable iff J†E_a†E_bJ=M_ab tensor I_L for every a,b. Equivalently P E_a†E_b P=J(M_ab tensor I_L)J†. The matrix-unit formulation uses embedded gauge units J(|k><l| tensor I)J† and is not an equality between operators on different spaces.',proof=['Necessity: decode recovered channel into G tensor L, trace G, and consider its Kraus rows with input gauge basis index. Reference-preserving identity on L implies each such row is a gauge functional tensor I_L by the scalar-Kraus lemma; sum recovery Kraus completeness to obtain the displayed operator-valued Gram matrix.', 'Sufficiency: regard E_a J(|k> tensor ·) as a combined error family indexed (a,k). Their pairwise Gram operators are scalar multiples of I_L. Ordinary KL constructs a common recovery to L for all these restrictions; linearity in gauge matrix units gives the exact logical marginal for correlated inputs. Re-encode with one fixed gauge state by a trace-preserving preparation channel.'])
# Fault model: reduced-state equality alone is insufficient and disjoint recursion must be a real hypothesis.
edit('def-qc-code-deviation-and-spread',s='For reference-preserving error propagation, a state is s-deviated from an encoded target when it belongs to the linear/error-channel span generated by operators supported on at most s physical coordinates of that target (include arbitrary reference tensor identity). This is not defined merely by equality of reduced states outside a support. A gadget has spread ell when each single supported fault term propagates to at most ell output coordinates per block; multi-fault supports use the union bound.')
edit('lem-qc-recursive-bad-rectangle-probability',s=by['lem-qc-recursive-bad-rectangle-probability']['statement_or_definition']+' Require 1≤q<a, and disjoint underlying elementary location sets for the children used in each product bound. Without disjointness, independent elementary faults do not imply independent child badness.')
edit('thm-qc-proper-code-concatenated-threshold',s=by['thm-qc-proper-code-concatenated-threshold']['statement_or_definition']+' The rectangle recursion must partition elementary fault locations into disjoint children, 1≤q<a, and every all-good gadget must satisfy its complete reference-preserving logical action contract; overlapping extended rectangles require the separate truncation analysis. Here d is a correction capacity, not minimum code distance.')
edit('thm-qc-t1-extended-rectangle-threshold',s=by['thm-qc-t1-extended-rectangle-threshold']['statement_or_definition']+' The product bound for overlapping exRecs is conditional on a proved truncated-exRec/disjoint-fault-witness reduction; the mere phrase “requires two faults” does not imply independent child events. Assume b≥2.')
# MBQC: define J and remove CZ-only layers incorrectly producing a free H.
add('def-qc-j-gate-and-equatorial-basis','definition','QC22','For real alpha, P_alpha=diag(1,e^(i alpha)), J(alpha)=H P_alpha; the ordered measurement basis is |b>_alpha=J(alpha)†|b>, b∈{0,1}. Retain this exact global phase convention.',['def-qc-one-qubit-gate-alphabet-and-rotations'],['J is unitary as a product of unitaries, so the two vectors are an orthonormal basis. Matrix multiplication gives J(−beta)X=e^(−i beta)ZJ(beta).'],source='https://arxiv.org/pdf/1907.09415',locator='Chapter 20.6 measurement-based quantum computation')
edit('lem-qc-one-bit-teleportation',deps=['def-qc-j-gate-and-equatorial-basis']);edit('lem-qc-adaptive-angle-pauli-frame-update',deps=['def-qc-j-gate-and-equatorial-basis'])
edit('def-qc-circuit-to-graph-resource-encoding',s='Normalize the circuit over J(alpha),CZ into transport rounds: each round consists of disjoint CZs followed by exactly one J(alpha) on every wire. Insert two successive J(0)=H transports wherever identity is needed; CZ-only layers therefore incur explicit extra transports whose product is identity. One round creates a next vertex on every wire and horizontal edges to it; its CZ edges are placed on current-column vertices before measurement. Inputs are first-column vertices, outputs last-column vertices. For R normalized rounds the graph has n(R+1) vertices; R=O(d+1) after bounded-factor expansion of disjoint circuit layers. Emit the ordered graph and the adaptive angle/Pauli-frame schedule, not an unqualified n(d+1) formula for arbitrary original layers.',deps=['def-qc-j-gate-and-equatorial-basis'])
edit('thm-qc-circuit-simulated-by-adaptive-pattern',proof=['For each transport round the arbitrary-input one-bit branch identity applies to every wire after the current CZ matching. Output Pauli frames propagate through CZ: X_c picks up Z_t and X_t picks up Z_c; commute them into the next equatorial measurement, flipping its angle and outcome bit as appropriate.', 'Maintain the exact branch scalar, frame, and norm invariant by induction over R rounds. Every transport contributes a fair bit; after final frame correction the output channel is the prescribed circuit, including reference correlations. Count the added identity transports; do not claim one graph column per unnormalized CZ-only layer.'])
edit('thm-qc-generic-circuit-count-lower-bound',s='Fix a finite gate alphabet of maximum arity k≤3, n classical input wires, zero-initialized ancillas and one designated measured output bit (no arbitrary classical acceptance predicate for free). Restrict to C≥n gates and at most n+kC+1 active wires after removing unused ancillas. There are at most sum_(j≤C)(A(n+kC+1)^k)^j output-designated descriptions, i.e. exp(O(C log C)). Each circuit can compute at most one Boolean function with success≥2/3 on every input. Counting against 2^(2^n) shows that for all sufficiently large n at least 99% of Boolean functions require Omega(2^n/n) gates. If arbitrary classical postprocessing is allowed, include its circuit/description cost; otherwise this conclusion is false.',proof=['Count every gate label, ordered wire tuple and chosen output wire. For C of order 2^n/n the logarithm of the description count is at most a chosen fixed fraction of 2^n; choose a sufficiently small constant.', 'For a fixed circuit, output-one probability cannot be ≥2/3 and ≤1/3 on the same input; hence each truth table has at most one interpretation. Divide the number of descriptions by 2^(2^n), absorbing polynomial factors.'])
# State/isometry preparation, exact finite instructions and genuine costs.
edit('alg-qc-state-preparation',s='Input n≥0 and a normalized exact amplitude table (a_x) of D=2^n entries in an ideal exact-arithmetic model supplying square roots, atan2 and complex arguments (no Turing bit bound presumed). Start |0^n>. Compute r_p=sqrt(sum_(x extends p)|a_x|²) for every prefix. In order of prefix lengths l=0,...,n−1 and lexicographic p, apply R_y(theta_p) to bit l controlled on prefix p, where theta_p=2 atan2(r_(p1),r_(p0)); choose theta_p=0 if r_p=0. For each nonzero a_x apply its phase arg(a_x) as a basis-state-selective phase; choose phase zero for a_x=0, omitting a common reference phase if ray output is requested. Expand every control with the stated clean Toffoli ladder and undo work after each call. Return the finite gate list and classical angle table; malformed/unnormalized input returns INVALID.',deps=['def-qc-ordered-bitstring-encoding','def-qc-toffoli-and-fredkin','thm-qc-multicontrolled-ancilla-resource-tradeoff'])
edit('thm-qc-state-preparation-rotation-level-upper-bound',s='For D=2^n, the prefix procedure exactly prepares the target ray using O(D) variable-control rotations and basis-selective phases. Expanding each with a clean Toffoli ladder gives O((n+1)D) bounded-arity gates and serial depth and O(n) clean work qubits in addition to n data qubits; n=0 is the trivial scalar ray.',deps=['thm-qc-multicontrolled-ancilla-resource-tradeoff'],proof=['Induct over prefix length: the amplitude of every prefix equals its subtree norm, since child/prefix ratios telescope; zero subtrees remain zero. Leaf phases give a_x up to the declared common scalar.', 'Compute each prefix equality flag using at most n−1 Toffolis into clean work, apply a one-control rotation/phase, and uncompute. For short controls use the corresponding one-/two-qubit primitives. Sum fewer than D magnitude nodes and at most D phases; include the n=0 branch.'])
edit('thm-qc-state-preparation-cost',s=by['thm-qc-state-preparation-cost']['statement_or_definition'].replace('O(nD)','O((n+1)D)').replace('O(n) clean ancillas/wires','O(n) clean work qubits in addition to n data qubits')+' Exact continuous compilation uses ideal arithmetic; finite-precision table normalization, certified angle computation and finite-alphabet approximation require the separate precision supplier before any bit-time claim.')
add('alg-qc-isometry-unitary-completion','algorithm','QC24','Input exact M×D isometry V with 1≤D≤M and explicit ordered bases, in ideal arithmetic with exact zero tests. Initialize list with its D columns. For each standard vector e_j, subtract its projections onto the current orthonormal list; if residual norm is zero skip, otherwise normalize and append. Stop when M vectors are present; return the unitary W with this list as columns, so its first D columns equal V. For qubit widths use the embedding of |x> tensor |0^a> as the declared first D input columns via an explicit basis permutation.',['thm-qc-two-level-unitary-elimination-correct','def-qc-tensor-register-and-permutation','def-qc-clean-and-dirty-ancillas'],['Finite j loop defines completion; exact zero test is an arithmetic capability. Correctness and gate cost are in the separate result.'],source='https://www.theory.caltech.edu/~preskill/ph219/chap5_15.pdf',locator='Chapter 5 unitary circuit decomposition; local finite Gram–Schmidt completion')
add('thm-qc-isometry-completion-and-synthesis','theorem','QC24','The completion algorithm returns a unitary extension of every finite isometry V:C^D→C^M. When M=2^w and D=2^n with w≥n, QC11 synthesis implements the isometry on the declared clean-input subspace with the same full-unitary gate upper bound; the extra output wires generally contain part of the encoded state and are not claimed to return to zero.',['alg-qc-isometry-unitary-completion','thm-qc-exact-arbitrary-unitary-qsd-upper-bound'],['Induct that the list is orthonormal and contains the original columns; if after all e_j fewer than M columns remained, every e_j would lie in its span, contradiction. Thus W†W=I.', 'Apply the declared basis permutation to clean-input coordinates and then W. Restrict the full-unitary operator equality to the first D columns, retaining all M output coordinates and counting extra output wires.'])
