root_home={}
for f in sorted(pathlib.Path('library').glob('*/*.md')):
 try:fm=yaml.safe_load(f.read_text().split('---',2)[1])
 except Exception:continue
 if isinstance(fm,dict) and fm.get('page'):
  for id in (fm.get('items') or [])+(fm.get('examples') or []):root_home.setdefault(id,fm['page'])
for p in pages['pages']:
 req=set(p['requires'])
